package main

import (
 "context"
 "encoding/json"
 "errors"
 "fmt"
 "net/http"
 "os"
 "path/filepath"
 "strings"
 "time"

 "researchos.local/research-os/internal/domain"
)

func prepare(ctx context.Context,s seed,digest string)(domain.Object,error){
 if err:=verifyEvidenceWorkspace(s);err!=nil{return nil,err}
 e,err:=openEnvironment(ctx,s);if err!=nil{return nil,err};defer e.close()
 // The data-root lease now serializes this check and the durable claim below.
 // A concurrent prepare can no longer observe absent state before waiting.
 if _,err=os.Stat(statePath(s));err==nil{return nil,errors.New("qualification preparation already claimed; inspect private state, no retry")}else if !errors.Is(err,os.ErrNotExist){return nil,err}
 if err=e.startHTTP(e.handler(nil));err!=nil{return nil,err}
 if err=verifyCLIProject(ctx,e,s);err!=nil{return nil,err}
 v:=state{Schema:schema,SeedSHA256:digest,HostInstanceID:e.host.InstanceID(),OwnerID:e.ownerID,ProjectID:s.ProjectID,DraftGoalID:s.DraftGoalID,Phase:"PREPARE_CLAIMED"}
 if err=saveState(s,v);err!=nil{return nil,err}
 // Once claimed, a failure is an observable partial setup. No automatic
 // second prepare call may create a duplicate goal, runtime or sealed profile.
 if err=prepareObjects(ctx,e,s,&v);err!=nil{return nil,err}
 v.Phase="PREPARED";if err=saveState(s,v);err!=nil{return nil,err}
 return domain.Object{"status":"PREPARED","project_id":v.ProjectID,"draft_goal_id":v.DraftGoalID,"qualification_goal_id":v.QualificationGoalID,"qualification_task_id":v.TaskID,"runtime_id":v.RuntimeID,"profile_artifact_id":v.ProfileID,"profile_hash":v.ProfileHash,"host_instance_id":v.HostInstanceID,"state_path":statePath(s),"provider_requests":0},nil
}

func verifyEvidenceWorkspace(s seed) error {
 dir,err:=os.Lstat(s.WorkspaceDir);if err!=nil{return err}
 if !dir.IsDir() || dir.Mode()&os.ModeSymlink!=0{return errors.New("witness workspace must be a real directory")}
 canonical,err:=filepath.EvalSymlinks(s.WorkspaceDir);if err!=nil{return err}
 if !strings.EqualFold(filepath.Clean(canonical),filepath.Clean(s.WorkspaceDir)){return errors.New("witness workspace reparse path refused")}
 entries,err:=os.ReadDir(s.WorkspaceDir);if err!=nil{return err}
 if len(entries)!=1 || entries[0].Name()!="evidence.txt" || entries[0].IsDir(){return errors.New("isolated workspace must contain exactly evidence.txt")}
 info,err:=os.Lstat(filepath.Join(s.WorkspaceDir,"evidence.txt"));if err!=nil{return err}
 if !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink!=0{return errors.New("witness must be a regular, non-link file")}
 hash,n,err:=fileHash(filepath.Join(s.WorkspaceDir,"evidence.txt"));if err!=nil{return err}
 if n!=s.WitnessBytes || !strings.EqualFold(strings.TrimPrefix(s.WitnessSHA256,"sha256:"),hash){return errors.New("workspace witness differs from pin")}
 return nil
}

func verifyCLIProject(ctx context.Context,e *environment,s seed) error {
 discovered,err:=os.ReadFile(s.DiscoveryFile);if err!=nil{return err}
 var firstHost struct{URL string `json:"url"`;PID int `json:"pid"`;DataDir string `json:"data_dir"`;HostInstanceID string `json:"host_instance_id"`}
 if err=json.Unmarshal(discovered,&firstHost);err!=nil{return err}
 if firstHost.HostInstanceID!=e.host.InstanceID() || !strings.EqualFold(filepath.Clean(firstHost.DataDir),filepath.Clean(e.lease.Root())) || firstHost.PID<1 || !strings.HasPrefix(firstHost.URL,"http://127.0.0.1:"){return errors.New("CLI initial discovery differs from actual same-SID Host")}
 raw,err:=os.ReadFile(s.CLIConfigFile);if err!=nil{return err}
 var cli struct{ProjectID string `json:"project_id"`;WorkspaceRef string `json:"workspace_ref"`}
 if err=json.Unmarshal(raw,&cli);err!=nil{return err}
 if cli.ProjectID!=s.ProjectID || cli.WorkspaceRef!=s.WorkspaceRef{return errors.New("CLI project/workspace differs from seed")}
 goal,err:=e.get(ctx,e.ownerToken,"/goals/"+s.DraftGoalID);if err!=nil{return err}
 if goal["project_id"]!=s.ProjectID || goal["status"]!="DRAFT" {return errors.New("target CLI goal is not a DRAFT in the same project")}
 var bindingRaw string
 err=e.db.QueryRowContext(ctx,"SELECT body FROM domain_objects WHERE kind='WorkspaceBinding' AND json_extract(body,'$.authorized_workspace_ref')=?",s.WorkspaceRef).Scan(&bindingRaw)
 if err!=nil{return err}
 var binding domain.Object;if err=json.Unmarshal([]byte(bindingRaw),&binding);err!=nil{return err}
 if binding["project_id"]!=s.ProjectID || binding["status"]!="ACTIVE" || !strings.EqualFold(filepath.Clean(domain.Str(binding,"real_path")),filepath.Clean(s.WorkspaceDir)){return errors.New("CLI workspace binding differs from exact isolated directory")}
 return checkUnlimited(ctx,e,"/budget-policy")
}

func checkUnlimited(ctx context.Context,e *environment,path string) error {
 p,err:=e.get(ctx,e.ownerToken,path);if err!=nil{return err}
 if p["mode"]!="UNLIMITED_AMOUNT" || p["cap"]!=nil || p["unknown_cost_action"]!="ALLOW_AND_RECORD" {return errors.New("unknown-cost trial requires existing unlimited budget ancestry")}
 return nil
}

func qualificationContract()domain.Object{
 c:=domain.Object{"contract_revision":1,"checks":[]any{domain.Object{"check_id":"mu-turn-output","kind":"DETERMINISTIC","required":true,"expected":"Bounded Mu response with exact user-message provenance and reconciled model/tool effects; execution is not independent acceptance","command_key":"mu.turn-output-v1","rubric_ref":nil,"qualification_id":nil,"not_applicable_reason":nil}},"require_independent_verifier":true,"version_policy":"EXACT","frozen_at":time.Now().UTC().Format(time.RFC3339Nano)}
